for r in unique.values():
 y,m,d=map(int,r['date'].split('-')); d=min(d,calendar.monthrange(y,m)[1]); dt=datetime.date(y,m,d)
 eid=alias.get(r['employee_id'],r['employee_id']); rate=float(emps[eid]['hourly_rate']); amt=float(r['salary_amount']); cum=amt/rate
 # first Tuesday of month, if before first Tuesday previous month
 first=datetime.date(y,m,1); pay=first+datetime.timedelta(days=(1-first.weekday())%7)
 if dt<pay:
